"""Pointer edits, chromatic notes, box selection, batch fields and tempo-position invariants."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path);p.add_argument('--url');a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1440,'height':1000},reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(a.url or (root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('#newSongBtn').click();page.locator('#createTitle').fill('鼠标与乐理编辑');page.locator('#createConfirm').click()
 page.evaluate('''()=>{const w=window.SKY_MUSIC_TEST,c=w.musicComposition(),track=c.tracks[0].id;c.notes=[{id:'C',trackId:track,pitch:60,startTick:480,durationTicks:480,soundTicks:432,gate:.9,velocity:70},{id:'E',trackId:track,pitch:64,startTick:480,durationTicks:960,soundTicks:960,gate:1,velocity:100},{id:'G',trackId:track,pitch:67,startTick:1440,durationTicks:480,soundTicks:480,gate:1,velocity:85}];w.musicRender();document.getElementById('musicRollViewport').scrollTop=(108-70)*w.mw.row}''')
 def xy(t,pitch):
  g=page.locator('#musicCanvas').bounding_box();row=page.evaluate('window.SKY_MUSIC_TEST.mw.row');scroll=page.locator('#musicRollViewport').evaluate('e=>({x:e.scrollLeft,y:e.scrollTop})');return g['x']+64+t*90/960-scroll['x'],g['y']+52+(108-pitch)*row-scroll['y']+11
 page.locator('#musicTool').select_option('draw');page.mouse.click(*xy(1920,61));assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.some(n=>n.pitch===61)')
 page.locator('#musicTool').select_option('select');x,y=xy(600,60);page.mouse.move(x,y);page.mouse.down();page.mouse.move(x+45,y-page.evaluate('window.SKY_MUSIC_TEST.mw.row'),steps=6);page.mouse.up();moved=page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.find(n=>n.id==="C")');assert moved['pitch']==61 and moved['startTick']==960,moved
 page.locator('#musicUndo').click();assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.find(n=>n.id==="C").pitch')==60
 x,y=xy(1440,64);page.mouse.move(x-2,y);page.mouse.down();page.mouse.move(x+43,y,steps=6);page.mouse.up();assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.find(n=>n.id==="E").durationTicks')==1440
 page.mouse.click(*xy(600,60));page.keyboard.down('Shift');page.mouse.click(*xy(600,64));page.keyboard.up('Shift');assert page.evaluate('window.SKY_MUSIC_TEST.mw.selected.size')==2
 page.locator('#musicPitch').fill('62');page.locator('#musicNoteValue').select_option('8');page.locator('#musicNoteGate').fill('50');page.locator('[data-music-action=applyNote]').click();notes=page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.filter(n=>["C","E"].includes(n.id))');assert [n['pitch'] for n in notes]==[62,66] and all(n['soundTicks']==240 for n in notes),notes
 page.locator('#musicUndo').click();x1,y1=xy(100,70);x2,y2=xy(2500,59);page.mouse.move(x1,y1);page.mouse.down();page.mouse.move(x2,y2,steps=8);page.mouse.up();assert page.evaluate('window.SKY_MUSIC_TEST.mw.selected.size')==4
 before=page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.length');page.locator('[data-music-action=copy]').click();page.evaluate('window.SKY_MUSIC_TEST.mw.cursor=3840');page.locator('[data-music-action=paste]').click();assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.length')==before*2
 invariant=page.evaluate('''()=>{const w=window.SKY_MUSIC_TEST,c=w.musicComposition();w.mw.cursor=960;w.MusicAudio.position=w.Music.tickMs(c,960);return c.notes.map(n=>[n.id,n.startTick,n.durationTicks])}''');page.locator('#musicBpm').fill('60');page.locator('[data-music-action=tempo]').click();assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes.map(n=>[n.id,n.startTick,n.durationTicks])')==invariant;assert page.evaluate('window.SKY_MUSIC_TEST.Music.msTick(window.SKY_MUSIC_TEST.musicComposition(),window.SKY_MUSIC_TEST.MusicAudio.position)')==960
 # Invalid meter placement rejects the whole transaction.
 before=page.evaluate('JSON.stringify(window.SKY_MUSIC_TEST.musicComposition())');page.locator('#musicMeter').select_option('6/8');page.locator('[data-music-action=meter]').click();assert page.evaluate('JSON.stringify(window.SKY_MUSIC_TEST.musicComposition())')==before
 page.screenshot(path=str(a.output/'gestures.png'));assert not errors,errors;b.close()
(a.output/'results.json').write_text(json.dumps({'passed':True,'pointerMoveResize':True,'chromaticDraw':True,'multiSelect':True,'tempoPositionPreserved':True,'errors':errors},indent=2),'utf-8');print('PASS draw, move, resize, multi-select, clipboard, batch fields, tempo and meter rejection')
